// WmaBlob.h
//
// Embedded WMA conformance fixture: a real WMA (wmav2) stream in an ASF
// container, 2 ch, 44100 Hz. It also exercises the ASF sniff carve-out: the blob
// begins with the 16-byte ASF_Header_Object GUID (30 26 B2 75 ...), which
// DecoderFactory routes straight to FFmpeg so Mpg123Decoder never sees the
// payload (the same false-sync hazard that bit raw DTS). Produced once with
// FFmpeg:
//
//   ffmpeg -f lavfi -i "sine=frequency=440:sample_rate=44100:duration=0.30" \
//          -ac 2 -c:a wmav2 -b:a 128k conf_wma.wma
//   xxd -i conf_wma.wma
//
// Included once, inside ConformanceTest.cpp's anonymous namespace and its
// RAWFORM_HAVE_FFMPEG guard.
